WITH enriched AS (SELECT id, order_id, method, amount, paid_at, status, AVG(amount) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS amount_avg_2_prior, RANK() OVER (PARTITION BY order_id, status ORDER BY amount DESC) AS amount_rank, STDDEV_SAMP(amount) OVER (PARTITION BY method, status) AS method_stddev_samp_amount FROM payments) SELECT id, order_id, method, amount, paid_at, status, amount_avg_2_prior, method_stddev_samp_amount FROM enriched ORDER BY method DESC, method_stddev_samp_amount DESC;
